type Mode = "AUTOPILOT" | "EXCEPTIONS" | "MANUAL";
type StageStatus = "PASSED_REUSED" | "READY" | "TOURNAMENT_RUNNING" | "WORK_PACKET_READY" | "ARTIFACT_GENERATING" | "ARTIFACT_READY" | "MICRO_QA_RUNNING" | "REPAIR_REQUIRED" | "VERIFIED" | "FROZEN" | "HANDOFF_READY" | "INVALIDATED" | "AWAITING_APPROVAL" | "ESCALATED" | "BLOCKED";
